function selectionKey(v){return v?JSON.stringify([v.provider,v.model]):'';}
function modelName(catalog,v,t){if(!v)return t('followModel');const group=catalog?.groups?.find(g=>g.id===v.provider);return (group?.name||v.provider)+' · '+(group?.models.find(m=>m.id===v.model)?.name||v.model);}
